const BASE_URL = "http://localhost:8000/books";

export async function listBooks() {
  const res = await fetch(BASE_URL);
  if (!res.ok) throw new Error("Failed to fetch books");
  return res.json();
}

export async function createBook(book) {
  const res = await fetch(BASE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(book),
  });
  if (!res.ok) throw new Error("Failed to create book");
  return res.json();
}

export async function updateBookStatus(id, status) {
  const res = await fetch(`${BASE_URL}/${id}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ status }),
  });
  if (!res.ok) throw new Error("Failed to update book");
  return res.json();
}

import { useEffect, useState } from "react";
import { listBooks } from "../api";

export default function BookList({ refreshKey }) {
  const [books, setBooks] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;
    listBooks()
      .then((data) => {
        if (!cancelled) setBooks(data);
      })
      .catch((err) => {
        if (!cancelled) setError(err.message);
      });
    return () => {
      cancelled = true;
    };
  }, [refreshKey]);

  if (error) return <p className="error">Error: {error}</p>;

  if (books.length === 0) return <p>No books yet. Add one!</p>;

  return (
    <ul className="book-list">
      {books.map((book) => (
        <li key={book.id} className="book-item">
          <strong>{book.title}</strong> — {book.author}
          <span className={`status status-${book.status}`}>{book.status}</span>
        </li>
      ))}
    </ul>
  );
}

import { useState } from "react";
import { createBook } from "../api";

export default function BookForm({ onBookCreated }) {
  const [title, setTitle] = useState("");
  const [author, setAuthor] = useState("");
  const [status, setStatus] = useState("to-read");
  const [error, setError] = useState(null);

  async function handleSubmit(e) {
    e.preventDefault();
    setError(null);
    try {
      await createBook({ title, author, status });
      setTitle("");
      setAuthor("");
      setStatus("to-read");
      onBookCreated();
    } catch (err) {
      setError(err.message);
    }
  }

  return (
    <form className="book-form" onSubmit={handleSubmit}>
      {error && <p className="error">{error}</p>}
      <label>
        Title:
        <input
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />
      </label>
      <label>
        Author:
        <input
          type="text"
          value={author}
          onChange={(e) => setAuthor(e.target.value)}
          required
        />
      </label>
      <label>
        Status:
        <select value={status} onChange={(e) => setStatus(e.target.value)}>
          <option value="to-read">To Read</option>
          <option value="reading">Reading</option>
          <option value="completed">Completed</option>
        </select>
      </label>
      <button type="submit">Add Book</button>
    </form>
  );
}

